CREATE OR REPLACE FUNCTION shorts_mvp.assert_language_test_job(p_job shorts_mvp.video_jobs)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'shorts_mvp', 'pg_temp'
AS $function$
declare r record; t jsonb;
begin
  if p_job.language_test_release_id='8af2c7e6-5421-4e93-9671-b0e8bb41de8a'::uuid
    or p_job.template_snapshot->>'snsTemplateVersion'='1' then
    perform shorts_mvp.assert_sns_template_job(p_job);
    return;
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('language_test_admission',0));
  perform singleton from shorts_mvp.language_test_settings where singleton for share;
  if not exists(
    select 1 from shorts_mvp.app_users u
    join shorts_mvp.language_test_settings s on s.singleton
    where u.id=p_job.user_id and (u.is_admin or s.public_rollout_percent=100)
  ) then
    raise exception 'LANGUAGE_PUBLIC_DISABLED';
  end if;
  select l.*,e.git_sha,e.worker_image_digest,e.font_manifest_sha256,e.status,e.staging_verified_at
    into r from shorts_mvp.language_test_settings s
    join shorts_mvp.language_test_releases l on l.id=s.release_id
    join shorts_mvp.editor_releases e on e.id=l.id
    where s.singleton and s.enabled and l.id=p_job.language_test_release_id
      and l.verified_at is not null and e.ui_version=3 and e.document_version=3
      and e.render_spec_version=4 and e.caption_render_spec_version=4 for share of s,l,e;
  if not found or r.status not in ('canary_ready','canary_active','approved') or r.staging_verified_at is null then
    raise exception 'LANGUAGE_TEST_UNAVAILABLE';
  end if;
  t:=r.registry->'lanes'->p_job.batch_target_key->'current';
  if t is null or p_job.initial_editor_release_id is distinct from r.id
    or p_job.batch_target_release_id is distinct from t->>'releaseId'
    or p_job.batch_job_definition is distinct from t->>'jobDefinitionArn'
    or p_job.batch_job_queue is distinct from t->>'jobQueueArn'
    or r.git_sha is distinct from t->>'workerSourceGitSha'
    or r.worker_image_digest is distinct from split_part(t->>'imageUri','@',2)
    or r.font_manifest_sha256 is distinct from t->>'fontManifestSha256'
    or coalesce(t->>'jobDefinitionArn','') !~ '^arn:aws:batch:ap-northeast-2:181651591905:job-definition/shorts-mvp-language-test-'
    or coalesce(t->>'jobQueueArn','') !~ '^arn:aws:batch:ap-northeast-2:181651591905:job-queue/shorts-mvp-language-test-'
  then raise exception 'LANGUAGE_TEST_TARGET_MISMATCH'; end if;
end; $function$

CREATE OR REPLACE FUNCTION shorts_mvp.enforce_language_test_editor_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'shorts_mvp', 'pg_temp'
AS $function$
declare pinned uuid;
begin
  select j.language_test_release_id into pinned from shorts_mvp.generated_shorts s
    join shorts_mvp.video_jobs j on j.id=s.job_id
    where s.id=new.short_id and s.user_id=new.user_id and j.user_id=new.user_id;
  if new.release_id in ('406dadcf-f290-4eb8-b82e-a6e8c6b40105'::uuid,'77d3b2de-12a4-4b7d-a134-87170b1d3ecf'::uuid,'4fbfeeaa-e210-4143-aece-c17029d962a0'::uuid,'66f640ba-d156-4c90-9c4f-f79038bf9d14'::uuid,'34df634e-d49a-4171-b3ea-f86199543ec1'::uuid,'c8324dfe-06f1-4765-b6d3-14410d8bd114'::uuid,'340f9382-c8b0-4926-acd0-b8a3987316e4'::uuid) then
    perform shorts_mvp.assert_sns_editor_request(new);
    return new;
  end if;
  if new.release_id in ('601d3d10-62b9-47f2-a34e-78b53ab1ec99'::uuid,'11a62875-b24a-4874-9794-4aac13b0c305'::uuid,'242f96a3-fe3b-4f20-a006-3c6559d98573'::uuid,'d1bb4c9d-f055-4cbe-bdbd-318e51ffdf33'::uuid,'ca57c1ae-c841-4f44-835a-f566a3c097c1'::uuid,'a576138e-1ddf-4469-8494-252058595705'::uuid,'6f50a87c-250c-4d3e-a8c9-b79d1fbc2f91'::uuid,'3355b631-73ec-4f0f-a669-1fd460d2c284'::uuid,'0f39f8e7-f4e7-48d1-9c0e-7735276ae06b'::uuid) then
    perform shorts_mvp.assert_community_editor_request(new);
    return new;
  end if;
  if pinned is not null then
    if new.release_id is distinct from pinned or new.release_channel<>'canary'
      or not exists(select 1 from shorts_mvp.language_test_releases where id=pinned and verified_at is not null) then
      raise exception 'LANGUAGE_TEST_EDITOR_BINDING_MISMATCH';
    end if;
  elsif exists(select 1 from shorts_mvp.language_test_releases where id=new.release_id) then
    raise exception 'LANGUAGE_TEST_EDITOR_BINDING_MISMATCH';
  end if;
  return new;
end; $function$
